<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useProject } from '@/composables/useProject'
import { repository } from '@/data/database'
import { createArchive } from '@/domain/archive'
import { exportModel } from '@/services/models'
import { deliverFile } from '@/services/files'
import { errorMessage } from '@/domain/validation'
import { toast } from '@/composables/useToasts'
import AppIcon from '@/components/AppIcon.vue'
import PageHeading from '@/components/PageHeading.vue'
import NoticeBox from '@/components/NoticeBox.vue'
const route = useRoute(), id = computed(() => String(route.params.id)), { project, scenes, loading, error } = useProject(id), format = ref<'w3d'|'glb'|'ply'|'obj'>('w3d'), encrypt = ref(false), password = ref(''), confirm = ref(''), acknowledged = ref(false), busy = ref(false), failure = ref('')
const formats = [{ id:'w3d' as const, title:'Full project backup', code:'W3D', text:'All scans, notes, photos, crops, room outlines and annotations. Restorable in this app.', icon:'folder' },{ id:'glb' as const, title:'Universal 3D scene', code:'GLB', text:'Transformed and cropped geometry with vertex colours. Multiple sections retain their names.', icon:'cube' },{ id:'ply' as const, title:'Point cloud & mesh', code:'PLY', text:'Binary geometry and vertex colours for 3D tools. Sections are combined.', icon:'scan' },{ id:'obj' as const, title:'Geometry exchange', code:'OBJ', text:'Text-based vertices and faces. Colour extensions may not be supported by every viewer.', icon:'layers' }]
async function run(share: boolean): Promise<void> {
 if (!project.value || busy.value) return; busy.value = true; failure.value = ''
 try { const blob = format.value === 'w3d' ? await createArchive(project.value, await repository.assets(id.value), encrypt.value ? password.value : undefined) : await exportModel(scenes.value, format.value); await deliverFile(blob, `${project.value.name}.${format.value}`, share); toast('Export prepared. Keep the resulting file somewhere safe.', 'success') } catch (e) { if (!(e instanceof DOMException && e.name === 'AbortError')) failure.value = errorMessage(e) } finally { busy.value = false; password.value = ''; confirm.value = '' }
}
const canExport = computed(() => acknowledged.value && !error.value && !busy.value && !!project.value && (format.value === 'w3d' || scenes.value.length > 0) && !(format.value === 'w3d' && encrypt.value && (password.value.length < 12 || password.value !== confirm.value)))
</script>
<template><div class="container export-container"><PageHeading :back="`/projects/${id}`" eyebrow="YOUR SPACE. YOUR FILES." title="Take it with you." subtitle="Back up your work or export geometry to your favourite 3D tools."/><NoticeBox v-if="error" kind="error">{{ error }}</NoticeBox><div v-if="loading" class="loading-state">Preparing export options…</div><div v-if="project" class="export-layout"><section class="card form-card"><h2>Choose a format</h2><label v-for="f in formats" :key="f.id" class="choice-card format-choice" :class="{ selected: format === f.id, disabled: f.id !== 'w3d' && !scenes.length }"><input v-model="format" type="radio" name="export-format" :value="f.id" :disabled="f.id !== 'w3d' && !scenes.length"><AppIcon :name="f.icon" :size="27"/><span><strong>{{ f.title }}<b class="format-code">{{ f.code }}</b></strong><small>{{ f.text }}</small></span></label><template v-if="format === 'w3d'"><label class="switch-row mt-4"><span><strong>Encrypt this backup</strong><small>Protect private scans and photos with a passphrase.</small></span><input v-model="encrypt" type="checkbox" role="switch"></label><template v-if="encrypt"><label class="form-label" for="export-password">Passphrase · at least 12 characters</label><input id="export-password" v-model="password" type="password" class="form-control" minlength="12" maxlength="1024" autocomplete="new-password"><label class="form-label" for="export-confirm">Confirm passphrase</label><input id="export-confirm" v-model="confirm" type="password" class="form-control" autocomplete="new-password"><NoticeBox kind="warning">Save your passphrase separately. This app cannot recover it or unlock a forgotten backup.</NoticeBox></template></template></section><aside><section class="card detail-card"><span class="eyebrow">EXPORT SUMMARY</span><h2 class="mt-2">{{ project.name }}</h2><div class="stat-pair"><span>Scan sections</span><strong>{{ project.scenes.length }}</strong></div><div class="stat-pair"><span>Included reference photos</span><strong>{{ format === 'w3d' ? project.photos.length : 0 }}</strong></div><div class="stat-pair"><span>Units</span><strong>Metres · Y up</strong></div><div class="stat-pair"><span>Destination</span><strong>Your device / chosen app</strong></div><label class="consent-check"><input v-model="acknowledged" type="checkbox"><span>I have reviewed this space for private belongings, people and sensitive details. I understand the exported file can be shared outside this app.</span></label><NoticeBox v-if="failure" kind="error">{{ failure }}</NoticeBox><button class="btn btn-primary btn-lg w-100" :disabled="!canExport" @click="run(false)"><AppIcon name="download"/>{{ busy ? 'Preparing file…' : 'Export file' }}</button><button class="btn btn-outline-primary w-100 mt-2" :disabled="!canExport" @click="run(true)"><AppIcon name="share" :size="18"/>Share a file</button></section><NoticeBox><strong>No automatic publication.</strong> This app does not create a public link or upload your home. Sharing sends only the file you deliberately choose. Backups include original uncropped scan data; geometry exports use the visible crop.</NoticeBox></aside></div></div></template>
